query.base:
TS metrics-gcp.compute.otel-*
// Compute Engine VM instances only.
// performance_status is one-hot: each disk emits Healthy, Degraded and Severely Degraded series every interval,
// with value 1 on the active status and 0 on the others. Only the value matters, not document counts.
// "Degraded" is routine GCE maintenance and is deliberately not alerted on.
| WHERE resource.attributes.gcp.resource_type == "gce_instance"
    AND attributes.performance_status == "Severely Degraded"
| STATS
    min_active = MIN(MIN_OVER_TIME(`compute.googleapis.com/instance/disk/performance_status`)),
    samples = SUM(COUNT_OVER_TIME(`compute.googleapis.com/instance/disk/performance_status`))
  BY resource.attributes.project_id, resource.attributes.zone, resource.attributes.instance_id, attributes.device_name, attributes.storage_type

breach.segment:
// Breach: Severely Degraded on EVERY sample in the window (persistent), with enough samples to be meaningful.
// Use MAX instead of MIN for a faster but noisier trigger on any sample.
WHERE min_active >= 1 AND samples >= 3
| KEEP resource.attributes.project_id, resource.attributes.zone, resource.attributes.instance_id, attributes.device_name, attributes.storage_type, samples
| SORT resource.attributes.zone ASC, resource.attributes.instance_id ASC
| LIMIT 100
